from tessel.atlas import Atlas, Node, Edge

def solve(edges, start, end):
    atlas = Atlas()

    # Add nodes to the atlas
    nodes = {node: Node(node) for node in set(u for u, v, _ in edges) | set(v for u, v, _ in edges)}
    for node in nodes.values():
        atlas.add_node(node)

    # Add edges to the atlas
    for u, v, cost in edges:
        edge = Edge(nodes[u], nodes[v], cost)
        atlas.add_edge(edge)

    # Find the cheapest route
    try:
        path = atlas.find_path(start, end, lambda e: e.cost)
        return [node.value for node in path]
    except Exception:
        return []
```

